    need(json.loads(source('DEPENDENCIES.json'))['external_canonical_mathematical_dependencies']==[],'Accepted dependency scope differs')
    need(re.findall(r'\[[^\]]*\]\(([^)\s#]+\.md)(?:#[^)]*)?\)',actual.decode())==[],'Undeclared canonical Markdown citation')
